pattern.example:
# In mcp_server/tests/test_home_assistant_integration.py import pytest import os from unittest.mock import AsyncMock, Mock, patch
class TestHomeAssistantIntegration: """End-to-end integration tests for Home Assistant tools."""
@pytest.mark.asyncio async def test_query_then_control_flow(self): """Test querying state, then controlling device, then verifying state change.""" # 1. Mock initial state query mock_query_response = { "status": "success", "entities": [{"entity_id": "light.living_room", "state": "off"}] }
# 2. Mock control action mock_control_response = { "status": "success", "entity_id": "light.living_room", "action": "turn_on", "previous_state": "off", "new_state": "on" }
with patch(...): # Query initial state query_result = await home_assistant_query_tool_handler( entity_ids=["light.living_room"] ) assert query_result["entities"][0]["state"] == "off"
# Control device control_result = await home_assistant_control_tool_handler( entity_id="light.living_room", action="turn_on" ) assert control_result["new_state"] == "on"
@pytest.mark.skipif( not os.getenv("HA_URL"), reason="Home Assistant not configured" ) @pytest.mark.asyncio async def test_real_ha_query(self): """Integration test with real Home Assistant (skipped if not available).""" result = await home_assistant_query_tool_handler(domain="light") assert result["status"] == "success" assert "entities" in result

# In backend/tests/test_mqtt_subscriber.py import pytest from unittest.mock import AsyncMock, Mock, patch
class TestMQTTSubscriberIntegration: """Integration tests for MQTT subscriber to Telegram flow."""
@pytest.fixture def mock_telegram_delivery(self): delivery = AsyncMock() delivery.send_proactive_message = AsyncMock( return_value=Mock(success=True, message_id="123") ) return delivery
@pytest.mark.asyncio async def test_mqtt_message_to_telegram_flow(self, mock_telegram_delivery): """Test full flow: MQTT message received → parsed → forwarded to Telegram.""" mqtt_message = { "title": "Motion Detected", "message": "Motion in backyard at 10:45 PM", "entity_id": "binary_sensor.backyard_motion" }
with patch('backend.api.mqtt_subscriber.TelegramDelivery', return_value=mock_telegram_delivery): subscriber = MQTTSubscriber(...) await subscriber.handle_message("annie/alerts/motion", json.dumps(mqtt_message))
# Verify Telegram was called with correct message mock_telegram_delivery.send_proactive_message.assert_called_once() call_args = mock_telegram_delivery.send_proactive_message.call_args assert "Motion Detected" in call_args[1]["message"]
